143	export class EvalQueries {
144	  static async getVarsFromEvals(evals: Eval[]) {
145	    const db = getDb();
146	
147	    // Handle empty array case to avoid SQL syntax error
148	    if (evals.length === 0) {
149	      return {};
150	    }
151	
152	    const evalIds = evals.map((e) => e.id);
153	
154	    // Use parameterized query to prevent SQL injection
155	    const query = sql`
156	      SELECT DISTINCT j.key, eval_id
157	      FROM (
158	        SELECT eval_id, json_extract(eval_results.test_case, '$.vars') as vars
159	        FROM eval_results
160	        WHERE eval_id IN (${sql.join(evalIds, sql`, `)})
161	      ) t, json_each(t.vars) j
162	    `;
163	
164	    const results = await db.all<VarKeyWithEvalIdResult>(query);
165	    const vars = results.reduce((acc: Record<string, string[]>, r) => {
166	      acc[r.eval_id] = acc[r.eval_id] || [];
167	      acc[r.eval_id].push(r.key);
168	      return acc;
169	    }, {});
170	    return vars;
171	  }
172	
173	  static async getVarsFromEval(evalId: string) {
174	    const db = getDb();
175	
176	    // Use parameterized query to prevent SQL injection
177	    const query = sql`
178	      SELECT DISTINCT j.key
179	      FROM (
180	        SELECT json_extract(eval_results.test_case, '$.vars') as vars
181	        FROM eval_results
182	        WHERE eval_results.eval_id = ${evalId}
183	      ) t, json_each(t.vars) j
184	    `;
185	
186	    const results = await db.all<VarKeyResult>(query);
187	    const vars = results.map((r) => r.key);
188	
189	    return vars;
190	  }
191	
192	  static async setVars(evalId: string, vars: string[]) {
193	    const db = getDb();
194	    try {
195	      db.update(evalsTable).set({ vars }).where(eq(evalsTable.id, evalId)).run();
196	    } catch (e) {
197	      logger.error(`Error setting vars: ${vars} for eval ${evalId}: ${e}`);
198	    }
199	  }
