201	  static async getMetadataKeysFromEval(
202	    evalId: string,
203	    comparisonEvalIds: string[] = [],
204	  ): Promise<string[]> {
205	    const db = getDb();
206	    try {
207	      // Combine primary eval ID with comparison eval IDs
208	      const allEvalIds = [evalId, ...comparisonEvalIds];
209	
210	      // Use json_valid() to filter out malformed JSON and add LIMIT for DoS protection
211	      const query = sql`
212	        SELECT DISTINCT j.key FROM (
213	          SELECT metadata FROM eval_results
214	          WHERE eval_id IN (${sql.join(allEvalIds, sql`, `)})
215	            AND metadata IS NOT NULL
216	            AND metadata != '{}'
217	            AND json_valid(metadata)
218	          LIMIT 10000
219	        ) t, json_each(t.metadata) j
220	        ORDER BY j.key
221	        LIMIT 1000
222	      `;
223	      const results = await db.all<MetadataKeyResult>(query);
224	      return results.map((r) => r.key);
225	    } catch (error) {
226	      // Log error but return empty array to prevent breaking the UI
227	      logger.error(
228	        `Error fetching metadata keys for eval ${evalId} and comparisons [${comparisonEvalIds.join(', ')}]: ${error}`,
229	      );
230	      return [];
231	    }
232	  }
