234	  /**
235	   * Queries all unique metadata values for a given metadata key.
236	   * @param evalId - The ID of the eval to get the metadata values from.
237	   * @param key - The key of the metadata to get the values from.
238	   * @returns An array of unique metadata values.
239	   */
240	  static getMetadataValuesFromEval(evalId: string, key: string): string[] {
241	    const db = getDb();
242	    const trimmedKey = key.trim();
243	    if (!trimmedKey) {
244	      return [];
245	    }
246	
247	    try {
248	      const jsonPath = buildSafeJsonPath(trimmedKey);
249	
250	      const query = sql`
251	        SELECT DISTINCT
252	          json_extract(${evalResultsTable.metadata}, ${jsonPath}) AS value
253	        FROM ${evalResultsTable}
254	        WHERE ${evalResultsTable.evalId} = ${evalId}
255	          AND ${evalResultsTable.metadata} IS NOT NULL
256	          AND ${evalResultsTable.metadata} != '{}'
257	          AND json_valid(${evalResultsTable.metadata})
258	          AND json_extract(${evalResultsTable.metadata}, ${jsonPath}) IS NOT NULL
259	        ORDER BY value
260	        LIMIT 1000
261	      `;
262	
263	      const rows = db.all<{ value: string }>(query);
264	      const values = rows
265	        .map(({ value }) => String(value).trim())
266	        .filter((value) => value.length > 0);
267	
268	      return Array.from(new Set(values));
269	    } catch (error) {
270	      logger.error(
271	        `Error fetching metadata values for eval ${evalId} and key ${trimmedKey}: ${error instanceof Error ? error.message : String(error)}`,
272	      );
273	      return [];
274	    }
275	  }
