552	  constructor(
553	    config: Partial<UnifiedConfig>,
554	    opts?: {
555	      id?: string;
556	      createdAt?: Date;
557	      author?: string | null;
558	      description?: string;
559	      prompts?: CompletedPrompt[];
560	      datasetId?: string;
561	      persisted?: boolean;
562	      vars?: string[];
563	      runtimeOptions?: Partial<import('../types').EvaluateOptions>;
564	      durationMs?: number;
565	      generationDurationMs?: number;
566	      evaluationDurationMs?: number;
567	    },
568	  ) {
569	    const createdAt = opts?.createdAt || new Date();
570	    this.createdAt = createdAt.getTime();
571	    this.id = opts?.id || createEvalId(createdAt);
572	    this.author = opts?.author ?? null;
573	    this.config = config;
574	    this.results = [];
575	    this.prompts = opts?.prompts || [];
576	    this.datasetId = opts?.datasetId;
577	    this.persisted = opts?.persisted || false;
578	    this._resultsLoaded = false;
579	    this.vars = opts?.vars || [];
580	    this.runtimeOptions = opts?.runtimeOptions;
581	    this.durationMs = opts?.durationMs;
582	    this.generationDurationMs = opts?.generationDurationMs;
583	    this.evaluationDurationMs = opts?.evaluationDurationMs;
584	  }
