586	  version() {
587	    /**
588	     * Version 3 is the denormalized version of where the table and results are stored on the eval object.
589	     * Version 4 is the normalized version where the results are stored in another databse table and the table for vizualization is generated by the app.
590	     */
591	    return this.oldResults && 'table' in this.oldResults ? 3 : 4;
592	  }
