604	  async save() {
605	    const db = getDb();
606	    const updateObj: Record<string, unknown> = {
607	      config: this.config,
608	      prompts: this.prompts,
609	      description: this.config.description,
610	      author: this.author,
611	      updatedAt: getCurrentTimestamp(),
612	      vars: Array.from(this.vars),
613	      runtimeOptions: sanitizeRuntimeOptions(this.runtimeOptions),
614	    };
615	
616	    if (this.useOldResults()) {
617	      invariant(this.oldResults, 'Old results not found');
618	      updateObj.results = this.oldResults;
619	    } else if (
620	      this.durationMs !== undefined ||
621	      this.generationDurationMs !== undefined ||
622	      this.evaluationDurationMs !== undefined
623	    ) {
624	      // For V4 evals, atomically merge duration fields into the results column
625	      // using json_set so concurrent save() calls don't clobber each other's keys.
626	      // Guard against malformed or non-object JSON (arrays, strings, null) in legacy rows.
627	      let expr: SQL = sql`CASE WHEN json_valid(${evalsTable.results}) AND json_type(${evalsTable.results}) = 'object' THEN ${evalsTable.results} ELSE '{}' END`;
628	      if (this.durationMs !== undefined) {
629	        expr = sql`json_set(${expr}, '$.durationMs', ${this.durationMs})`;
630	      }
